// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller 'from', one recipient address in the _tos array, and a value v
    function testFuzz_property(address from, address to, uint256 v) public {
        // keep to non-zero so array element is meaningful; allow to be any address (including contracts)
        vm.assume(to != address(0));

        address[] memory tos = new address[](1);
        tos[0] = to;

        // We need the callee at 'to' to have code so that the low-level call inside transfer behaves like a contract call.
        // Deploy a benign callee that implements transferFrom and returns true; if 'to' equals the deployed helper address,
        // the low-level call will hit it; otherwise the call will go to an EOA and still succeed (call to EOA returns true).
        // Deploy helper and ensure its address is used by the fuzzer when equal to 'to' by allowing any 'to'.
        HelperReceiver helper = new HelperReceiver();

        // If the fuzzed 'to' equals the helper address, use it (so we exercise a contract callee); otherwise use 'to' as given.
        address caddress = to;
        if (to == address(0) || to == address(1)) {
            // avoid some reserved addresses if necessary
            caddress = address(helper);
        }
        // To ensure some inputs use the helper, also allow passing the helper address directly when fuzz picks it.
        // Call transfer and capture its boolean result using try/catch to read returned bool.
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General property: for any non-empty _tos, reference C returns true; the mutant returns false for some such inputs.
        // Assert that the call returned true. This will hold for the reference and fail for the mutant on some inputs.
        assertTrue(ok);
    }
}

// Minimal helper that will be used as a contract callee; its transferFrom simply returns true.
contract HelperReceiver {
    // mimic target selector transferFrom(address,address,uint256)
    // We implement a function matching the selector so low-level call succeeds and returns true.
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // accept arbitrary calls as well
    fallback() external payable {
        // do nothing, allow call to succeed
    }
}
